-- Nullable detail payload preserves old writers during a rolling deployment.
alter table public.ai_usage_events
  add column if not exists usage_details jsonb;
comment on column public.ai_usage_events.usage_details is
  'Provider-reported cache, reasoning, audio and upstream details. Null means unknown; cost is estimated, not a provider invoice.';

